select aj1_0.batch_id,count(wsc1_0.id),coalesce(sum(case when wsc1_0.review_status<>'PENDING_REVIEW' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='PENDING' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='PROCESSING' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='FAILED' and wsc1_0.comparison_failure_code='AI_TOKEN_QUOTA_EXHAUSTED' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='FAILED' and wsc1_0.comparison_failure_code='AI_TOKEN_QUOTA_EXHAUSTED' and (aj1_0.analysis_mode='ORDERED_PROVISIONAL' or (aj1_0.review_mode='AUTOMATIC' and aj1_0.automatic_applied_at is null and aj1_0.status in ('PENDING','RUNNING'))) then 1 else 0 end),0) from world_setting_candidates wsc1_0 join analysis_jobs aj1_0 on aj1_0.id=wsc1_0.analysis_job_id where wsc1_0.work_id='47e524ae-e53c-5b8b-b430-905990a20f3d' and aj1_0.batch_id in ('551540e7-15da-551b-99d2-fa32ac754bcb','651dff26-6e30-589a-9981-6dc04c6259ba') and aj1_0.source_kind='EPISODE' group by aj1_0.batch_id;
